package pe.animetv;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import java.util.*;import java.nio.charset.StandardCharsets;import org.jsoup.Jsoup;import static org.junit.Assert.*;import static pe.animetv.Models.*;
@RunWith(RobolectricTestRunner.class)
public class JkAnimeSourceTest {
 static String fixture(String name)throws Exception{try(var in=JkAnimeSourceTest.class.getResourceAsStream("/jkanime/"+name)){return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}
 static class Pages implements JkAnimeSource.Pages {List<String> requests=new ArrayList<>();public String get(String url)throws Exception{requests.add(url);return fixture(url.contains("buscar")?"search.html":url.contains("directorio")?"catalog.html":url.endsWith("horario")?"calendar.html":url.endsWith("psyren/")?"detail.html":url.endsWith("psyren/2/")?"episode.html":"recent.html");}public String episodes(String url,String token,String referer)throws Exception{assertEquals("fixture-token",token);requests.add(url);return fixture("episodes-4972.json");}}
 @Test public void detailUsesActualEpisodeNumbersAndDoesNotTrustZeroHtmlCount()throws Exception{Pages p=new Pages();Source s=new JkAnimeSource("https://jkanime.net",p);Detail d=s.detail(new Anime("","https://jkanime.net/psyren/",""));assertEquals(2,d.episodes().size());assertEquals("https://jkanime.net/psyren/2/",d.episodes().get(1).url());assertEquals("En emisión",d.status());assertEquals("2026",d.year());assertFalse(d.genres().isEmpty());assertSame(d,s.detail(d.anime()));assertEquals(2,p.requests.size());}
 @Test public void nativeAndExternalServersDecodeWithoutDownloadRoutes()throws Exception{var servers=JkAnimeSource.parseServers(Jsoup.parse(fixture("episode.html"),"https://jkanime.net/psyren/2/"));assertEquals(9,servers.size());assertTrue(servers.stream().anyMatch(s->s.name().equals("Mega")&&s.url().contains("/embed/")));assertTrue(servers.stream().anyMatch(s->s.name().equals("Streamwish")));assertTrue(servers.stream().allMatch(s->s.language().equals("SUB")));assertFalse(servers.stream().anyMatch(s->s.name().equals("Mediafire")||s.url().contains("jkanime.net/d/")));}
 @Test public void oldEpisodeIncludesDesukaAlongsideDesuAndMagi()throws Exception{var servers=JkAnimeSource.parseServers(Jsoup.parse(fixture("old.html")));assertTrue(servers.stream().anyMatch(s->s.name().equals("Desuka")));assertEquals(9,servers.size());}
 @Test public void desuAndMagiExtractRealHlsNotCoverOrAdvertisement()throws Exception{for(String host:List.of("desu","magi")){String url=JkStreams.ownUrl(Jsoup.parse(fixture(host+".html"),"https://jkanime.net/jkplayer/um"));assertTrue(url.startsWith("https://nika.playmudos.com/"));assertTrue(url.contains(".m3u8"));}}
 @Test public void streamwishDictionaryIsDecodedAsData()throws Exception{String url=JkStreams.wishUrl(Jsoup.parse(fixture("wish.html")),"https://flaswish.com/e/test");assertTrue(url.startsWith("https://flaswish.com/stream/"));assertTrue(url.endsWith("master.m3u8"));assertEquals(3,JkStreams.wishUrls(Jsoup.parse(fixture("wish.html")),"https://flaswish.com/e/test").size());assertFalse(url.contains("popunder"));}
 @Test public void catalogUsesCorrectNativeFilterAndPaginationKeys()throws Exception{Pages p=new Pages();Source s=new JkAnimeSource("https://jkanime.net",p);assertFalse(s.catalog("",1,Map.of("genre","accion","fecha","2012")).isEmpty());var u=okhttp3.HttpUrl.get(p.requests.get(0));assertEquals("1",u.queryParameter("p"));assertEquals("accion",u.queryParameter("genero"));assertEquals("2012",u.queryParameter("fecha"));assertNull(u.queryParameter("page"));}
 @Test public void searchReturnsFamilyAndPaginatesWithoutRepeating()throws Exception{Source s=new JkAnimeSource("https://jkanime.net",new Pages());var first=s.catalog("sword art online",1,Map.of());assertTrue(first.size()>5);assertTrue(first.stream().allMatch(a->a.title().contains("Sword Art Online")));assertTrue(s.catalog("sword art online",2,Map.of()).isEmpty());assertEquals("Finalizado",first.get(0).status());}
 @Test public void filtersExposeOnlySupportedKeysIncludingYear()throws Exception{Source s=new JkAnimeSource("https://jkanime.net",new Pages());var filters=s.filters();assertEquals(5,filters.size());assertTrue(filters.stream().anyMatch(f->f.key().equals("fecha")&&f.values().contains("2012")));assertTrue(filters.stream().allMatch(f->f.values().get(0).isBlank()));}
 @Test public void combinedSearchFiltersCheckActualMetadata()throws Exception{Source s=new JkAnimeSource("https://jkanime.net",new Pages());Detail d=new Detail(new Anime("SAO","",""),"",List.of(),List.of(new Genre("Acción","accion")),"Serie","2012","Finalizado");assertTrue(s.matchesFilters(d,Map.of("tipo","animes","fecha","2012","estado","finalizados","genre","accion")));assertFalse(s.matchesFilters(d,Map.of("fecha","2026")));assertFalse(s.matchesFilters(d,Map.of("tipo","peliculas")));}
 @Test public void recentAndCalendarUseCanonicalOriginalSourceLinks()throws Exception{Source s=new JkAnimeSource("https://jkanime.net",new Pages());assertFalse(s.recent().isEmpty());var calendar=s.calendar();assertTrue(calendar.size()>10);assertTrue(calendar.stream().allMatch(e->e.day()>=1&&e.day()<=7));assertTrue(calendar.stream().allMatch(e->e.anime().url().matches("https://jkanime.net/[^/]+/")));}
 @Test public void sourceIdentityAndDefaultSurviveHistory()throws Exception{assertTrue(Sources.ids().contains("jkanime"));assertEquals("jkanime",Sources.forUrl("https://jkanime.net/psyren/",Sources.create("latanime")).id());assertEquals("JKAnime",Sources.create("jkanime").name());assertEquals("ask",new Store(org.robolectric.RuntimeEnvironment.getApplication()).serverDefault("jkanime"));assertEquals("Voe",PlayerActivity.serverCaption(new Server("Voe","","SUB"),"jkanime"));}
 @Test public void megaSupportsOfficialEmbedLinks()throws Exception{assertArrayEquals(new String[]{"EIUnyCSC","QAz6xkPS-_RUVlPcu-yhWyRmhHn13H-K3pK0OJ2E6F4"},MegaStreams.link("https://mega.nz/embed/EIUnyCSC#QAz6xkPS-_RUVlPcu-yhWyRmhHn13H-K3pK0OJ2E6F4"));}
 @Test public void paginatedLegacyEpisodesKeepRealFinalEpisode()throws Exception{JkAnimeSource.Pages pages=new JkAnimeSource.Pages(){public String get(String url)throws Exception{return fixture("sao-detail.html");}public String episodes(String url,String token,String referer)throws Exception{return fixture(url.endsWith("/2")?"episodes-591-page2.json":"episodes-591.json");}};Source source=new JkAnimeSource("https://jkanime.net",pages);Detail d=source.detail(new Anime("SAO","https://jkanime.net/sword-art-online/",""));assertEquals(25,d.episodes().size());assertEquals("https://jkanime.net/sword-art-online/25/",d.episodes().get(24).url());assertEquals("Finalizado",d.status());assertEquals("2012",d.year());var related=source.related(d);assertEquals(4,related.size());assertTrue(related.get(0).url().contains("extra-edition"));assertTrue(related.stream().allMatch(a->!a.image().isBlank()));}
 @Test public void rejectsRepeatedEpisodePageInsteadOfSilentlyTruncating()throws Exception{JkAnimeSource.Pages pages=new JkAnimeSource.Pages(){public String get(String url)throws Exception{return fixture("sao-detail.html");}public String episodes(String url,String token,String referer)throws Exception{return fixture("episodes-591.json");}};try{new JkAnimeSource("https://jkanime.net",pages).detail(new Anime("SAO","https://jkanime.net/sword-art-online/",""));fail();}catch(java.io.IOException expected){assertTrue(expected.getMessage().contains("paginación"));}}
 @Test public void officialCdnArtworkUsesSiteReferer(){assertEquals("https://jkanime.net/",ArtworkHttp.request("https://cdn.jkdesa.com/assets/images/animes/image/psyren.jpg").header("Referer"));}
 @Test public void rejectsIncompleteFinalPage()throws Exception{JkAnimeSource.Pages pages=new JkAnimeSource.Pages(){public String get(String url)throws Exception{return fixture("sao-detail.html");}public String episodes(String url,String token,String referer)throws Exception{return url.endsWith("/2")?"{current_page:2,last_page:2,data:[]}":fixture("episodes-591.json");}};try{new JkAnimeSource("https://jkanime.net",pages).detail(new Anime("SAO","https://jkanime.net/sword-art-online/",""));fail();}catch(java.io.IOException expected){assertTrue(expected.getMessage().contains("incompleto"));}}
 @Test public void repeatedCatalogLookupSharesOneNativeResponse()throws Exception{Pages pages=new Pages();Source source=new JkAnimeSource("https://jkanime.net",pages);var first=source.catalog("",1,Map.of());assertSame(first,source.catalog("",1,Map.of()));assertEquals(1,pages.requests.size());}
}
